function animateIn(el, className){
  requestAnimationFrame(()=>{ requestAnimationFrame(()=>{ el.classList.add(className); }); });
}
function closeSidebarThenRender(afterFn){
  const aside = document.querySelector('.sidebar');
  const backdrop = document.querySelector('.sidebar-backdrop');
  if(sidebarOpen && aside && window.innerWidth<=900){
    aside.classList.remove('open');
    if(backdrop) backdrop.classList.remove('open');
    sidebarOpen = false;
    setTimeout(afterFn, 260); // matches the CSS transition duration
  }else{
    sidebarOpen = false;
    afterFn();
  }
}
function goToTab(tab){
  closeSidebarThenRender(()=>{
    if(!['dashboard','private','classes','settings','certificate','exam','whiteboard','game-maker','smart-board'].includes(tab)) return;
    activeTab = tab;
    // Remember the selected section and keep it in the URL so refresh returns here.
    try { localStorage.setItem('dania_active_tab', tab); } catch(e) {}
    try {
      const nextUrl = new URL(window.location.href);
      nextUrl.searchParams.set('tab', tab);
      window.history.replaceState({}, '', nextUrl.pathname + nextUrl.search + nextUrl.hash);
    } catch(e) {}
    activeStudentId=null; activeClassId=null; expandedSessionId=null; showNewSessionForm=false;
    if(tab==='certificate' && !cert) initCertState();
    if(tab==='exam' && !examBuilder) initExamBuilder();
    if(tab==='whiteboard' && !vboard) initVBoard();
    render();
  });
}
