function getAttendance(session, sid){
  const a = session.attendance[sid];
  if(!a) return {status:null, note:''};
  if(typeof a === 'string') return {status:a, note:''}; // backward compatibility with older records
  return {status:a.status||null, note:a.note||''};
}
function setAttendanceStatus(session, sid, status){
  const cur = getAttendance(session, sid);
  session.attendance[sid] = {status, note:cur.note};
}
function setAttendanceNote(session, sid, note){
  const cur = getAttendance(session, sid);
  session.attendance[sid] = {status:cur.status, note};
}
