function vbIcon(name, size, ink){
  size = size||24;
  return `<svg width="${size}" height="${size}" viewBox="0 0 32 32" style="overflow:visible${ink?`;--vb-ink:${ink}`:''}" aria-hidden="true">${VB_ICONS[name]||''}</svg>`;
}
const VB_TOOLS = [
  {id:'select',  label:'انتخاب و جابه‌جایی'},
  {id:'pen',     label:'قلم'},
  {id:'hl',      label:'هایلایت'},
  {id:'erase',   label:'پاک‌کن'},
  {id:'line',    label:'خط'},
  {id:'arrow',   label:'فلش'},
  {id:'fill',    label:'سطل رنگ'},
  {id:'text',    label:'متن'},
];
const VB_SHAPES = [
  {id:'rect', label:'مستطیل', icon:'rect'},
  {id:'ellipse', label:'بیضی', icon:'ellipse'},
  {id:'triangle', label:'مثلث', icon:'triangle'},
  {id:'diamond', label:'لوزی', icon:'diamond'},
  {id:'pentagon', label:'پنج‌ضلعی', icon:'pentagon'},
  {id:'hexagon', label:'شش‌ضلعی', icon:'hexagon'},
  {id:'star', label:'ستاره', icon:'star'},
  {id:'heart', label:'قلب', icon:'heart'},
  {id:'plusShape', label:'علامت +', icon:'plusShape'},
  {id:'trapezoid', label:'ذوزنقه', icon:'trapezoid'},
  {id:'parallelogram', label:'متوازی‌الاضلاع', icon:'parallelogram'},
  {id:'octagon', label:'هشت‌ضلعی', icon:'octagon'},
  {id:'rightTriangle', label:'مثلث قائم‌الزاویه', icon:'rightTriangle'},
  {id:'cross', label:'علامت ضربدر', icon:'cross'},
  {id:'arrowShape', label:'فلش پهن', icon:'arrowShape'},
];
let vboard = null;
let vbSaveTimer = null;

function initVBoard(){
  vboard = {pages:[vbNewPage([])], page:0, sel:null, tool:'pen', color:'#111111', size:4, bg:'white'};
  try{
    const raw = localStorage.getItem('dashboardVBoard');
    if(raw){
      const d = JSON.parse(raw);
      if(d && Array.isArray(d.pages) && d.pages.length){
        vboard.pages = d.pages.map(p=>vbNewPage(p.strokes));
        vboard.bg = VB_BGS.some(b=>b.id===d.bg) ? d.bg : 'white';
        vboard.color = ['white','grid','lines','english2'].includes(vboard.bg) ? '#111111' : '#ffffff';
      }
    }
  }catch(e){}
}
function vbScheduleSave(){
  clearTimeout(vbSaveTimer);
  vbSaveTimer = setTimeout(()=>{
    try{
      localStorage.setItem('dashboardVBoard', JSON.stringify({bg:vboard.bg, pages:vboard.pages.map(p=>({strokes:p.strokes}))}));
    }catch(e){ /* storage full or unavailable — the board still works in memory */ }
  }, 600);
}
function vbBgDef(){ return VB_BGS.find(b=>b.id===vboard.bg) || VB_BGS[0]; }

function vbDrawBackground(ctx){
  const bg = vbBgDef();
  ctx.save();
  ctx.fillStyle = bg.color; ctx.fillRect(0,0,VB_W,VB_H);
  ctx.strokeStyle = 'rgba(80,100,140,.22)'; ctx.lineWidth = 1;
  ctx.beginPath();
  if(bg.pattern==='grid'){
    for(let x=VB_GRID;x<VB_W;x+=VB_GRID){ ctx.moveTo(x+.5,0); ctx.lineTo(x+.5,VB_H); }
    for(let y=VB_GRID;y<VB_H;y+=VB_GRID){ ctx.moveTo(0,y+.5); ctx.lineTo(VB_W,y+.5); }
  }else if(bg.pattern==='lines'){
    for(let y=VB_GRID+10;y<VB_H;y+=VB_GRID){ ctx.moveTo(0,y+.5); ctx.lineTo(VB_W,y+.5); }
  }else if(bg.pattern==='english2'){
    // English handwriting guide: two horizontal baselines in each writing row.
    const row=92, gap=34, start=42;
    for(let y=start;y<VB_H;y+=row){
      ctx.moveTo(0,y+.5); ctx.lineTo(VB_W,y+.5);
      ctx.moveTo(0,y+gap+.5); ctx.lineTo(VB_W,y+gap+.5);
    }
  }
  ctx.stroke();
  ctx.restore();
}

let vbScratch = null;
function vbScratchCtx(){ if(!vbScratch) vbScratch = document.createElement('canvas').getContext('2d'); return vbScratch; }
function vbNewPage(strokes){
  strokes = Array.isArray(strokes) ? strokes : [];
  return {strokes, hist: strokes.map(st=>({k:'add', st})), redo:[]};
}
// Wraps a text stroke inside its box; returns the lines to draw and the box height.
function vbTextLayout(ctx, st){
  const size = st.size, lh = size*1.4, pad = st.bw ? VB_TEXT_PAD : 0;
  ctx.font = `600 ${size}px Vazirmatn, Tahoma, sans-serif`;
  ctx.textBaseline = 'top';
  const maxW = st.bw ? st.bw - pad*2 : Infinity;
  let y = st.a[1] + pad;
  const lines = [];
  String(st.text).split('\n').forEach(par=>{
    const rtl = /[\u0600-\u06FF]/.test(par);
    ctx.direction = rtl ? 'rtl' : 'ltr';
    const x = st.bw ? (rtl ? st.a[0]+st.bw-pad : st.a[0]+pad) : st.a[0];
    const wrapped = [];
    let line = '';
    par.split(/\s+/).filter(Boolean).forEach(w=>{
      const test = line ? line+' '+w : w;
      if(line && ctx.measureText(test).width > maxW){ wrapped.push(line); line = w; }
      else line = test;
    });
    wrapped.push(line);
    wrapped.forEach(l=>{ lines.push({t:l, rtl, x, y}); y += lh; });
  });
  return {lines, lh, h: y - st.a[1] + pad};
}
function vbBounds(st){
  let x1,y1,x2,y2;
  if(st.t==='text'){
    const c = vbScratchCtx();
    c.save();
    const lay = vbTextLayout(c, st);
    if(st.bw){ x1=st.a[0]; x2=st.a[0]+st.bw; }
    else{
      x1=Infinity; x2=-Infinity;
      lay.lines.forEach(l=>{ const w=c.measureText(l.t).width; if(l.rtl){ x1=Math.min(x1,l.x-w); x2=Math.max(x2,l.x); } else { x1=Math.min(x1,l.x); x2=Math.max(x2,l.x+w); } });
      if(!isFinite(x1)){ x1=st.a[0]; x2=st.a[0]+10; }
    }
    y1=st.a[1]; y2=st.a[1]+lay.h;
    c.restore();
    return {x1,y1,x2,y2};
  }
  const pts = st.pts || [st.a, st.b];
  x1=Infinity;y1=Infinity;x2=-Infinity;y2=-Infinity;
  pts.forEach(p=>{ x1=Math.min(x1,p[0]); y1=Math.min(y1,p[1]); x2=Math.max(x2,p[0]); y2=Math.max(y2,p[1]); });
  const r = st.t==='hl' ? st.w*2 : (st.t==='arrow' ? Math.max(14, st.w*4) : st.w/2+1);
  return {x1:x1-r, y1:y1-r, x2:x2+r, y2:y2+r};
}
function vbTranslate(st, dx, dy){
  if(st.pts) st.pts = st.pts.map(p=>[p[0]+dx, p[1]+dy]);
  if(st.a) st.a = [st.a[0]+dx, st.a[1]+dy];
  if(st.b) st.b = [st.b[0]+dx, st.b[1]+dy];
}
function vbScale(st, f, cx, cy){
  const sx=(x)=>cx+(x-cx)*f, sy=(y)=>cy+(y-cy)*f;
  if(st.pts) st.pts = st.pts.map(p=>[sx(p[0]), sy(p[1])]);
  if(st.a) st.a = [sx(st.a[0]), sy(st.a[1])];
  if(st.b) st.b = [sx(st.b[0]), sy(st.b[1])];
  if(st.t==='text'){ st.size *= f; if(st.bw) st.bw *= f; }
  else st.w = Math.max(0.5, st.w*f);
}
function vbCloneStroke(st){ return JSON.parse(JSON.stringify(st)); }
function vbRestoreStroke(st, snap){
  Object.keys(st).forEach(k=>delete st[k]);
  Object.assign(st, vbCloneStroke(snap));
}
function vbResizeStrokeToBounds(st, oldB, newB){
  const ow=Math.max(1,oldB.x2-oldB.x1), oh=Math.max(1,oldB.y2-oldB.y1);
  const nw=Math.max(1,newB.x2-newB.x1), nh=Math.max(1,newB.y2-newB.y1);
  const mx=x=>newB.x1+(x-oldB.x1)*nw/ow, my=y=>newB.y1+(y-oldB.y1)*nh/oh;
  if(st.pts) st.pts=st.pts.map(p=>[mx(p[0]),my(p[1])]);
  if(st.a) st.a=[mx(st.a[0]),my(st.a[1])];
  if(st.b) st.b=[mx(st.b[0]),my(st.b[1])];
  if(st.t==='text'){
    const f=Math.max(.1,Math.min(10,Math.sqrt((nw/ow)*(nh/oh))));
    st.size=Math.max(6,st.size*f);
    if(st.bw) st.bw=Math.max(30,nw);
  }else{
    const f=Math.max(.1,Math.min(10,Math.sqrt((nw/ow)*(nh/oh))));
    st.w=Math.max(.5,st.w*f);
  }
}
function vbHandleAt(b,pt,tol){
  const x1=b.x1-10,y1=b.y1-10,x2=b.x2+10,y2=b.y2+10,cx=(b.x1+b.x2)/2,cy=(b.y1+b.y2)/2;
  const hs=[['nw',x1,y1],['n',cx,y1],['ne',x2,y1],['e',x2,cy],['se',x2,y2],['s',cx,y2],['sw',x1,y2],['w',x1,cy]];
  for(const h of hs) if(Math.hypot(pt[0]-h[1],pt[1]-h[2])<=Math.max(10,tol)) return h[0];
  return null;
}
function vbResizeCursor(handle){
  return ({nw:'nwse-resize',se:'nwse-resize',ne:'nesw-resize',sw:'nesw-resize',n:'ns-resize',s:'ns-resize',e:'ew-resize',w:'ew-resize'})[handle]||'default';
}
function vbDistSeg(p, a, b){
  const dx=b[0]-a[0], dy=b[1]-a[1], l2=dx*dx+dy*dy;
  let t = l2 ? ((p[0]-a[0])*dx+(p[1]-a[1])*dy)/l2 : 0;
  t = Math.max(0, Math.min(1, t));
  return Math.hypot(p[0]-(a[0]+t*dx), p[1]-(a[1]+t*dy));
}
// pass 1: precise hit (on the line / text box). pass 2: also hits the inside of empty rectangles and ellipses.
function vbHit(st, pt, tol, pass){
  if(st.t==='erase') return false;
  if(st.t==='pen' || st.t==='hl'){
    const r = (st.t==='hl' ? st.w*2 : st.w/2) + tol;
    const p = st.pts;
    if(p.length===1) return Math.hypot(pt[0]-p[0][0], pt[1]-p[0][1]) <= r;
    for(let i=1;i<p.length;i++){ if(vbDistSeg(pt,p[i-1],p[i]) <= r) return true; }
    return false;
  }
  if(st.t==='line' || st.t==='arrow') return vbDistSeg(pt, st.a, st.b) <= st.w/2 + tol;
  if(st.t==='rect'){
    const [x1,y1]=st.a,[x2,y2]=st.b;
    const L=Math.min(x1,x2), R=Math.max(x1,x2), T=Math.min(y1,y2), B=Math.max(y1,y2);
    const r = st.w/2 + tol;
    if(vbDistSeg(pt,[L,T],[R,T])<=r || vbDistSeg(pt,[R,T],[R,B])<=r || vbDistSeg(pt,[R,B],[L,B])<=r || vbDistSeg(pt,[L,B],[L,T])<=r) return true;
    return pass===2 && pt[0]>=L && pt[0]<=R && pt[1]>=T && pt[1]<=B;
  }
  if(st.t==='ellipse'){
    const cx=(st.a[0]+st.b[0])/2, cy=(st.a[1]+st.b[1])/2;
    const rx=Math.abs(st.b[0]-st.a[0])/2, ry=Math.abs(st.b[1]-st.a[1])/2;
    if(rx<1 || ry<1) return Math.hypot(pt[0]-cx,pt[1]-cy) <= Math.max(rx,ry)+tol;
    const v = Math.hypot((pt[0]-cx)/rx, (pt[1]-cy)/ry);
    if(Math.abs(v-1)*Math.min(rx,ry) <= st.w/2 + tol) return true;
    return pass===2 && v<=1;
  }
  if(['triangle','diamond','pentagon','hexagon','star','heart','plusShape','trapezoid','parallelogram','octagon','rightTriangle','cross','arrowShape'].includes(st.t)){
    const b=vbBounds(st);
    return pass===2 && pt[0]>=b.x1-tol && pt[0]<=b.x2+tol && pt[1]>=b.y1-tol && pt[1]<=b.y2+tol;
  }
  if(st.t==='text'){
    const b = vbBounds(st);
    return pt[0]>=b.x1-tol && pt[0]<=b.x2+tol && pt[1]>=b.y1-tol && pt[1]<=b.y2+tol;
  }
  return false;
}
function vbPickAt(strokes, pt, tol){
  for(let pass=1; pass<=2; pass++){
    for(let i=strokes.length-1;i>=0;i--){ if(vbHit(strokes[i], pt, tol, pass)) return strokes[i]; }
  }
  return null;
}

function vbDrawStroke(ctx, st){
  ctx.save();
  ctx.lineCap='round'; ctx.lineJoin='round';
  ctx.strokeStyle = st.c; ctx.fillStyle = st.c;
  if(st.t==='erase'){
    ctx.globalCompositeOperation='destination-out';
    ctx.lineWidth = st.w*4;
  }else if(st.t==='hl'){
    ctx.globalAlpha = .35; ctx.lineCap='butt'; ctx.lineWidth = st.w*4;
  }else{
    ctx.lineWidth = st.w;
  }
  if(st.t==='pen' || st.t==='hl' || st.t==='erase'){
    const p = st.pts;
    if(p.length===1){
      ctx.beginPath(); ctx.arc(p[0][0],p[0][1],ctx.lineWidth/2,0,Math.PI*2);
      ctx.fillStyle = st.t==='erase' ? '#000' : st.c; ctx.fill();
    }else if(p.length>1){
      ctx.beginPath(); ctx.moveTo(p[0][0],p[0][1]);
      for(let i=1;i<p.length-1;i++){
        const mx=(p[i][0]+p[i+1][0])/2, my=(p[i][1]+p[i+1][1])/2;
        ctx.quadraticCurveTo(p[i][0],p[i][1],mx,my);
      }
      const l = p[p.length-1]; ctx.lineTo(l[0],l[1]);
      ctx.stroke();
    }
  }else if(st.t==='line' || st.t==='arrow'){
    const [x1,y1]=st.a,[x2,y2]=st.b;
    ctx.beginPath(); ctx.moveTo(x1,y1); ctx.lineTo(x2,y2); ctx.stroke();
    if(st.t==='arrow'){
      const ang=Math.atan2(y2-y1,x2-x1), hl=Math.max(14, st.w*4);
      ctx.beginPath();
      ctx.moveTo(x2,y2); ctx.lineTo(x2-hl*Math.cos(ang-Math.PI/7), y2-hl*Math.sin(ang-Math.PI/7));
      ctx.moveTo(x2,y2); ctx.lineTo(x2-hl*Math.cos(ang+Math.PI/7), y2-hl*Math.sin(ang+Math.PI/7));
      ctx.stroke();
    }
  }else if(st.t==='rect'){
    const [x1,y1]=st.a,[x2,y2]=st.b;
    const rx=Math.min(x1,x2), ry=Math.min(y1,y2), rw=Math.abs(x2-x1), rh=Math.abs(y2-y1);
    if(st.fill){ ctx.fillStyle=st.fill; ctx.fillRect(rx,ry,rw,rh); }
    ctx.strokeRect(rx,ry,rw,rh);
  }else if(st.t==='ellipse'){
    const [x1,y1]=st.a,[x2,y2]=st.b;
    ctx.beginPath();
    ctx.ellipse((x1+x2)/2,(y1+y2)/2,Math.abs(x2-x1)/2,Math.abs(y2-y1)/2,0,0,Math.PI*2);
    if(st.fill){ ctx.fillStyle=st.fill; ctx.fill(); }
    ctx.stroke();
  }else if(['triangle','diamond','pentagon','hexagon','star','heart','plusShape','trapezoid','parallelogram','octagon','rightTriangle','cross','arrowShape'].includes(st.t)){
    const [x1,y1]=st.a,[x2,y2]=st.b;
    const L=Math.min(x1,x2), R=Math.max(x1,x2), T=Math.min(y1,y2), B=Math.max(y1,y2);
    const cx=(L+R)/2, cy=(T+B)/2, w=R-L, h=B-T;
    ctx.beginPath();
    if(st.t==='triangle'){
      ctx.moveTo(cx,T); ctx.lineTo(R,B); ctx.lineTo(L,B); ctx.closePath();
    }else if(st.t==='diamond'){
      ctx.moveTo(cx,T); ctx.lineTo(R,cy); ctx.lineTo(cx,B); ctx.lineTo(L,cy); ctx.closePath();
    }else if(st.t==='pentagon' || st.t==='hexagon'){
      const n=st.t==='pentagon'?5:6, rr=Math.min(w,h)/2;
      for(let i=0;i<n;i++){ const a=-Math.PI/2+i*2*Math.PI/n; const x=cx+rr*Math.cos(a), y=cy+rr*Math.sin(a); i?ctx.lineTo(x,y):ctx.moveTo(x,y); }
      ctx.closePath();
    }else if(st.t==='star'){
      const outer=Math.min(w,h)/2, inner=outer*.45;
      for(let i=0;i<10;i++){ const a=-Math.PI/2+i*Math.PI/5, rr=i%2?inner:outer; const x=cx+rr*Math.cos(a), y=cy+rr*Math.sin(a); i?ctx.lineTo(x,y):ctx.moveTo(x,y); }
      ctx.closePath();
    }else if(st.t==='heart'){
      const top=cy-h*.18, bottom=B;
      ctx.moveTo(cx,bottom);
      ctx.bezierCurveTo(L+w*.08,cy+h*.18,L,top-h*.28,cx-w*.34,top);
      ctx.bezierCurveTo(cx-w*.13,top-h*.22,cx-w*.04,top-h*.22,cx,top+h*.04);
      ctx.bezierCurveTo(cx+w*.04,top-h*.22,cx+w*.13,top-h*.22,cx+w*.34,top);
      ctx.bezierCurveTo(R,top-h*.28,R-w*.08,cy+h*.18,cx,bottom);
      ctx.closePath();
    }else if(st.t==='trapezoid'){
      ctx.moveTo(L+w*.22,T); ctx.lineTo(R-w*.22,T); ctx.lineTo(R,B); ctx.lineTo(L,B); ctx.closePath();
    }else if(st.t==='parallelogram'){
      ctx.moveTo(L+w*.25,T); ctx.lineTo(R,T); ctx.lineTo(R-w*.25,B); ctx.lineTo(L,B); ctx.closePath();
    }else if(st.t==='octagon'){
      const cut=Math.min(w,h)*.28; ctx.moveTo(L+cut,T); ctx.lineTo(R-cut,T); ctx.lineTo(R,T+cut); ctx.lineTo(R,B-cut); ctx.lineTo(R-cut,B); ctx.lineTo(L+cut,B); ctx.lineTo(L,B-cut); ctx.lineTo(L,T+cut); ctx.closePath();
    }else if(st.t==='rightTriangle'){
      ctx.moveTo(L,T); ctx.lineTo(L,B); ctx.lineTo(R,B); ctx.closePath();
    }else if(st.t==='cross'){
      ctx.moveTo(L+w*.35,T); ctx.lineTo(L+w*.65,T); ctx.lineTo(L+w*.65,T+h*.35); ctx.lineTo(R,T+h*.35); ctx.lineTo(R,T+h*.65); ctx.lineTo(L+w*.65,T+h*.65); ctx.lineTo(L+w*.65,B); ctx.lineTo(L+w*.35,B); ctx.lineTo(L+w*.35,T+h*.65); ctx.lineTo(L,T+h*.65); ctx.lineTo(L,T+h*.35); ctx.lineTo(L+w*.35,T+h*.35); ctx.closePath();
    }else if(st.t==='arrowShape'){
      ctx.moveTo(L,T+h*.32); ctx.lineTo(L+w*.62,T+h*.32); ctx.lineTo(L+w*.62,T); ctx.lineTo(R,cy); ctx.lineTo(L+w*.62,B); ctx.lineTo(L+w*.62,T+h*.68); ctx.lineTo(L,T+h*.68); ctx.closePath();
    }else{
      ctx.rect(L,cy-h*.16,w,h*.32); ctx.rect(cx-w*.16,T,w*.32,h);
    }
    if(st.fill){ ctx.fillStyle=st.fill; ctx.fill(); }
    ctx.stroke();
  }else if(st.t==='text'){
    // The text lives in a box of fixed width (st.bw) and wraps inside it, so it never leaves the board.
    const lay = vbTextLayout(ctx, st);
    lay.lines.forEach(l=>{
      ctx.direction = l.rtl ? 'rtl' : 'ltr';
      ctx.textAlign = l.rtl ? 'right' : 'left';
      if(l.t) ctx.fillText(l.t, l.x, l.y);
    });
  }
  ctx.restore();
}

function renderVBoardScreen(root){
  const vb = vboard;
  const root0 = document.createElement('div');
  root0.className = 'vb-root';
  const pg = ()=>vb.pages[vb.page];

  // ---------- toolbar ----------
  const bar = document.createElement('div');
  bar.className = 'vb-bar';
  bar.innerHTML = `
    <div class="vb-group" data-g="tools">${VB_TOOLS.map(t=>`<button class="vb-tool${vb.tool===t.id?' active':''}" data-tool="${t.id}" title="${t.label}" aria-label="${t.label}">${vbIcon(t.id,24,vb.color)}</button>`).join('')}
      <div class="vb-shapes-wrap" id="vb-shapes-wrap">
        <button class="vb-tool${VB_SHAPES.some(x=>x.id===vb.tool)?' active':''}" id="vb-shapes-btn" type="button" title="شکل‌ها" aria-label="شکل‌ها" aria-expanded="false">${vbIcon('shapes',24)}<span class="vb-shape-label">شکل‌ها</span></button>
        <div class="vb-shapes-panel" id="vb-shapes-panel">${VB_SHAPES.map(sh=>`<button type="button" class="vb-shape-option${vb.tool===sh.id?' active':''}" data-shape="${sh.id}" title="${sh.label}" aria-label="${sh.label}">${vbIcon(sh.icon,24)}</button>`).join('')}</div>
      </div>
    </div>
    <div class="vb-sep"></div>
    <div class="vb-group" data-g="colors">${VB_COLORS.map(c=>`<button class="vb-swatch${vb.color===c?' active':''}" data-color="${c}" style="background:${c}" title="رنگ"></button>`).join('')}
      <input type="color" id="vb-custom" value="${vb.color}" title="رنگ دلخواه" style="width:30px;height:30px;border:none;background:none;padding:0;cursor:pointer;"></div>
    <div class="vb-group"><span id="vb-sizelabel" class="vb-sizelabel">ضخامت</span>
      <button class="vb-tool" id="vb-size-dec" title="کم کردن" aria-label="کم کردن">${vbIcon('sizeMinus',24)}</button>
      <input id="vb-size-range" class="vb-size-range" type="range" min="1" max="100" step="1" value="${vb.size}" aria-label="ضخامت">
      <button class="vb-tool" id="vb-size-inc" title="زیاد کردن" aria-label="زیاد کردن">${vbIcon('sizePlus',24)}</button>
      <input id="vb-sizeval" class="vb-sizeval" type="text" inputmode="numeric" autocomplete="off" aria-label="عدد ضخامت" title="عدد دلخواه را بنویسید و Enter بزنید">
      <span id="vb-sizeunit" class="vb-sizeunit"></span></div>
    <div class="vb-sep"></div>
    <div class="vb-group">
      <button class="vb-tool" id="vb-undo" title="برگردان (Ctrl+Z)" aria-label="برگردان">${vbIcon('undo',24)}</button>
      <button class="vb-tool" id="vb-redo" title="از نو (Ctrl+Y)" aria-label="از نو">${vbIcon('redo',24)}</button>
      <button class="vb-tool" id="vb-clear" title="پاک کردن این صفحه" aria-label="پاک کردن صفحه">${vbIcon('trash',24)}</button>
    </div>
    <div class="vb-sep"></div>
    <div class="vb-group">
      <button class="vb-tool" id="vb-prev" title="صفحهٔ قبل" aria-label="صفحهٔ قبل">${vbIcon('prev',22)}</button>
      <span class="vb-pagelabel" id="vb-pagelabel"></span>
      <button class="vb-tool" id="vb-next" title="صفحهٔ بعد" aria-label="صفحهٔ بعد">${vbIcon('next',22)}</button>
      <button class="vb-tool" id="vb-addpage" title="صفحهٔ جدید" aria-label="صفحهٔ جدید">${vbIcon('plus',22)}<span class="vb-tool-text">صفحه</span></button>
      <button class="vb-tool" id="vb-delpage" title="حذف این صفحه" aria-label="حذف صفحه">${vbIcon('close',22)}</button>
    </div>
    <div class="vb-sep"></div>
    <div class="vb-group vb-media-group">
      <select id="vb-bg" class="vb-tool" style="padding:0 8px;" title="پس‌زمینه">${VB_BGS.map(b=>`<option value="${b.id}"${vb.bg===b.id?' selected':''}>${b.label}</option>`).join('')}</select>
      <button class="vb-tool" id="vb-png" title="دانلود صفحه به صورت تصویر" aria-label="دانلود صفحه به صورت تصویر">${vbIcon('download',22)}<span class="vb-tool-text">تصویر</span></button>
      <button class="vb-tool" id="vb-full" title="تمام‌صفحه" aria-label="تمام‌صفحه">${vbIcon('full',22)}<span class="vb-tool-text">تمام‌صفحه</span></button>
    </div>`;
  root0.appendChild(bar);

  // ---------- stage ----------
  const stage = document.createElement('div');
  stage.className = 'vb-stage';
  const bgCanvas = document.createElement('canvas');
  const canvas = document.createElement('canvas');
  stage.appendChild(bgCanvas); stage.appendChild(canvas);
  root0.appendChild(stage);
  root.appendChild(root0);

  const K = Math.min(2, Math.max(1, window.devicePixelRatio||1));
  [bgCanvas, canvas].forEach(c=>{ c.width=Math.round(VB_W*K); c.height=Math.round(VB_H*K); });
  const bgCtx = bgCanvas.getContext('2d');
  const ctx = canvas.getContext('2d');
  const base = document.createElement('canvas'); base.width=canvas.width; base.height=canvas.height;
  const baseCtx = base.getContext('2d');
  const setScale = (c)=>c.setTransform(K,0,0,K,0,0);
  setScale(bgCtx); setScale(ctx); setScale(baseCtx);

  let cur = null;
  let drag = null;   // {st, last, dx, dy} while a selected object is being moved
  let resizeDrag = null; // {st, handle, start, oldBounds, before}
  function paintBg(){ bgCtx.clearRect(0,0,VB_W,VB_H); vbDrawBackground(bgCtx); }
  function rebuildBase(skip){
    baseCtx.save(); baseCtx.setTransform(1,0,0,1,0,0); baseCtx.clearRect(0,0,base.width,base.height); baseCtx.restore();
    pg().strokes.forEach(st=>{ if(st!==skip) vbDrawStroke(baseCtx, st); });
  }
  function paint(){
    ctx.save(); ctx.setTransform(1,0,0,1,0,0); ctx.clearRect(0,0,canvas.width,canvas.height);
    ctx.drawImage(base,0,0); ctx.restore();
    if(cur) vbDrawStroke(ctx, cur);
    if(drag) vbDrawStroke(ctx, drag.st);
    if(resizeDrag) vbDrawStroke(ctx, resizeDrag.st);
    if(vb.sel && !pg().strokes.includes(vb.sel)) vb.sel = null;
    syncSizeUi();
    if(vb.sel && vb.tool==='select'){
      const b = vbBounds(vb.sel), pd = 8;
      ctx.save();
      ctx.strokeStyle = '#5B47E0'; ctx.lineWidth = 2; ctx.setLineDash([8,6]);
      ctx.strokeRect(b.x1-pd, b.y1-pd, b.x2-b.x1+pd*2, b.y2-b.y1+pd*2);
      ctx.setLineDash([]); ctx.fillStyle = '#fff';
      [[b.x1-pd,b.y1-pd],[b.x2+pd,b.y1-pd],[b.x1-pd,b.y2+pd],[b.x2+pd,b.y2+pd]].forEach(([x,y])=>{ ctx.fillRect(x-5,y-5,10,10); ctx.strokeRect(x-5,y-5,10,10); });
      ctx.restore();
    }
  }
  function refreshUi(){
    bar.querySelector('#vb-undo').disabled = pg().hist.length===0;
    bar.querySelector('#vb-redo').disabled = pg().redo.length===0;
    bar.querySelector('#vb-prev').disabled = vb.page===0;
    bar.querySelector('#vb-next').disabled = vb.page===vb.pages.length-1;
    bar.querySelector('#vb-delpage').disabled = vb.pages.length<=1;
    bar.querySelector('#vb-pagelabel').textContent = `صفحه ${(vb.page+1).toLocaleString('fa-IR')} از ${vb.pages.length.toLocaleString('fa-IR')}`;
  }
  function redrawAll(){ paintBg(); rebuildBase(); paint(); refreshUi(); }

  // ---------- sizing: keep 16:9 and fit available space ----------
  function fit(){
    const fs = document.fullscreenElement===root0;
    const availW = root0.clientWidth - (fs?20:0);
    const barH = bar.offsetHeight;
    const availH = fs ? window.innerHeight - barH - 36 : Math.max(320, window.innerHeight - barH - 130);
    let w = Math.min(availW, availH*VB_W/VB_H);
    w = Math.max(280, w);
    stage.style.width = w+'px';
    stage.style.height = (w*VB_H/VB_W)+'px';
  }
  fit();
  const onResize = ()=>{ if(!document.body.contains(root0)){ window.removeEventListener('resize', onResize); document.removeEventListener('fullscreenchange', onResize); document.removeEventListener('keydown', onKey); return; } fit(); };
  window.addEventListener('resize', onResize);
  document.addEventListener('fullscreenchange', onResize);

  // ---------- pointer drawing ----------
  const toLogical = (e)=>{
    const r = stage.getBoundingClientRect();
    return [ (e.clientX-r.left)*VB_W/r.width, (e.clientY-r.top)*VB_H/r.height ];
  };
  function commit(st){
    pg().strokes.push(st); pg().hist.push({k:'add', st}); pg().redo = [];
    vbDrawStroke(baseCtx, st);
    vbScheduleSave();
  }
  let textInput = null;
  function closeTextInput(save){
    if(!textInput) return;
    const inp = textInput; textInput = null;
    const v = inp.value.replace(/\s+$/,'').replace(/^\s*\n/,'');
    const pos = inp._pos, bw = inp._bw, size = inp._size, color = inp._color;
    inp.remove();
    if(save && v.trim()){
      commit({t:'text', c:color, text:v, a:pos, bw, size});
      paint(); refreshUi();
    }
  }
  function openTextInput(pt){
    closeTextInput(true);
    const r = stage.getBoundingClientRect();
    const k = r.width/VB_W;
    const size = Math.max(20, vb.size*2.6);
    const bw = Math.min(Math.max(VB_TEXT_W, size*7), VB_W-20);
    // keep the whole box inside the board: shift it left/up when the click is near an edge
    const bx = Math.max(10, Math.min(pt[0], VB_W-bw-10));
    const by = Math.max(10, Math.min(pt[1], VB_H - size*1.4 - 20));
    const lum = (()=>{ const c=vb.color.replace('#',''); const n=parseInt(c.length===3?c.split('').map(x=>x+x).join(''):c,16); return (0.299*(n>>16)+0.587*((n>>8)&255)+0.114*(n&255))/255; })();
    const inp = document.createElement('textarea');
    inp.className = 'vb-text-input';
    inp.dir = 'auto';
    inp.rows = 1;
    inp.placeholder = 'متن را بنویسید ...';
    inp._pos = [bx,by]; inp._bw = bw; inp._size = size; inp._color = vb.color;
    inp.style.left = (bx*k)+'px';
    inp.style.top = (by*k)+'px';
    inp.style.width = (bw*k)+'px';
    inp.style.padding = (VB_TEXT_PAD*k)+'px';
    inp.style.fontSize = (size*k)+'px';
    inp.style.color = vb.color;
    inp.style.background = lum>0.6 ? 'rgba(0,0,0,.55)' : 'rgba(255,255,255,.75)';
    const grow = ()=>{ inp.style.height='auto'; inp.style.height = inp.scrollHeight+'px'; };
    inp.oninput = grow;
    inp.onkeydown = (ev)=>{
      ev.stopPropagation();
      if(ev.key==='Enter' && !ev.shiftKey){ ev.preventDefault(); closeTextInput(true); }
      else if(ev.key==='Escape'){ closeTextInput(false); }
    };
    inp.onblur = ()=>closeTextInput(true);
    stage.appendChild(inp); textInput = inp;
    grow();
    setTimeout(()=>inp.focus(), 0);
  }

  canvas.addEventListener('pointerdown', (e)=>{
    if(e.pointerType==='mouse' && e.button!==0) return;
    e.preventDefault();
    const pt = toLogical(e);
    if(vb.tool==='text'){ openTextInput(pt); return; }
    closeTextInput(true);
    if(vb.tool==='fill'){
      const hit = vbPickAt(pg().strokes, pt, Math.max(8, 12/(stage.getBoundingClientRect().width/VB_W)));
      if(hit && ['rect','ellipse','triangle','diamond','pentagon','hexagon','star','heart','plusShape','trapezoid','parallelogram','octagon','rightTriangle','cross','arrowShape'].includes(hit.t)){
        const before = hit.fill || null;
        const after = vb.color;
        if(before !== after){
          hit.fill = after;
          pg().hist.push({k:'fill',st:hit,before,after}); pg().redo=[];
          rebuildBase(); paint(); refreshUi(); vbScheduleSave();
        }
      }
      return;
    }
    if(vb.tool==='select'){
      const scale = stage.getBoundingClientRect().width / VB_W;
      const hit = vbPickAt(pg().strokes, pt, Math.max(8, 12/scale));
      if(vb.sel){
        const hb = vbHandleAt(vbBounds(vb.sel), pt, Math.max(12, 16/scale));
        if(hb){
          canvas.setPointerCapture(e.pointerId);
          resizeDrag = {st:vb.sel, handle:hb, start:pt, oldBounds:vbBounds(vb.sel), before:vbCloneStroke(vb.sel)};
          rebuildBase(vb.sel);
          canvas.style.cursor = vbResizeCursor(hb);
          paint();
          return;
        }
      }
      vb.sel = hit;
      if(hit){
        canvas.setPointerCapture(e.pointerId);
        drag = {st:hit, last:pt, dx:0, dy:0};
        canvas.style.cursor = 'grabbing';
        rebuildBase(hit);
      }
      paint();
      return;
    }
    canvas.setPointerCapture(e.pointerId);
    if(vb.tool==='pen' || vb.tool==='hl' || vb.tool==='erase'){
      cur = {t:vb.tool, c:vb.color, w:vb.size, pts:[pt]};
    }else{
      cur = {t:vb.tool, c:vb.color, w:vb.size, a:pt, b:pt};
    }
    paint();
  });
  canvas.addEventListener('pointermove', (e)=>{
    if(resizeDrag){
      const pt=toLogical(e), r=resizeDrag.oldBounds, h=resizeDrag.handle, min=18;
      let x1=r.x1,x2=r.x2,y1=r.y1,y2=r.y2;
      if(h.includes('w')) x1=Math.min(pt[0],x2-min);
      if(h.includes('e')) x2=Math.max(pt[0],x1+min);
      if(h.includes('n')) y1=Math.min(pt[1],y2-min);
      if(h.includes('s')) y2=Math.max(pt[1],y1+min);
      vbRestoreStroke(resizeDrag.st, resizeDrag.before);
      vbResizeStrokeToBounds(resizeDrag.st,r,{x1,y1,x2,y2});
      // Remove the old copy from the base before drawing the live-resized object.
      rebuildBase(resizeDrag.st);
      paint();
      canvas.style.cursor=vbResizeCursor(h);
      return;
    }
    if(drag){
      const pt = toLogical(e);
      const ddx = pt[0]-drag.last[0], ddy = pt[1]-drag.last[1];
      vbTranslate(drag.st, ddx, ddy);
      drag.dx += ddx; drag.dy += ddy; drag.last = pt;
      paint();
      return;
    }
    if(vb.tool==='select' && !cur && !drag && !resizeDrag && e.pointerType!=='touch'){
      const scale = stage.getBoundingClientRect().width / VB_W;
      const pt=toLogical(e);
      const handle=vb.sel ? vbHandleAt(vbBounds(vb.sel),pt,Math.max(12,16/scale)) : null;
      canvas.style.cursor = handle ? vbResizeCursor(handle) : (vbPickAt(pg().strokes, pt, Math.max(8, 12/scale)) ? 'move' : 'default');
    }
    if(!cur) return;
    const evs = e.getCoalescedEvents ? e.getCoalescedEvents() : [e];
    (evs.length?evs:[e]).forEach(ev=>{
      const pt = toLogical(ev);
      if(cur.pts){
        const l = cur.pts[cur.pts.length-1];
        if(Math.hypot(pt[0]-l[0],pt[1]-l[1])>=1.2) cur.pts.push(pt);
      }else cur.b = pt;
    });
    paint();
  });
  const endStroke = (e)=>{
    if(resizeDrag){
      const r=resizeDrag; resizeDrag=null;
      const p=pg();
      const after=vbCloneStroke(r.st);
      const before=r.before;
      if(JSON.stringify(before)!==JSON.stringify(after)){
        const idx=p.strokes.indexOf(r.st);
        p.hist.push({k:'resize',st:r.st,before,after,idx}); p.redo=[]; vbScheduleSave();
      }
      canvas.style.cursor='move';
      rebuildBase(); paint(); refreshUi();
      return;
    }
    if(drag){
      const d = drag; drag = null;
      const p = pg();
      if(Math.hypot(d.dx,d.dy) > 0.5){
        const from = p.strokes.indexOf(d.st);
        let to = from;
        // an eraser stroke drawn later must not "bite" the moved object: bring it to the top
        if(p.strokes.slice(from+1).some(x=>x.t==='erase')){ p.strokes.splice(from,1); p.strokes.push(d.st); to = p.strokes.length-1; }
        p.hist.push({k:'move', st:d.st, dx:d.dx, dy:d.dy, from, to}); p.redo = [];
        vbScheduleSave();
      }
      canvas.style.cursor = 'move';
      rebuildBase(); paint(); refreshUi();
      return;
    }
    if(!cur) return;
    const st = cur; cur = null;
    commit(st); paint(); refreshUi();
  };
  canvas.addEventListener('pointerup', endStroke);
  canvas.addEventListener('pointercancel', endStroke);
  canvas.addEventListener('contextmenu', e=>e.preventDefault());

  // ---------- toolbar actions ----------
  const setActive = (sel, attr, val)=>bar.querySelectorAll(sel).forEach(b=>b.classList.toggle('active', b.dataset[attr]===val));
  bar.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{ closeTextInput(true); vb.tool=b.dataset.tool; vb.sel=null; setActive('[data-tool]','tool',vb.tool); bar.querySelectorAll('[data-shape]').forEach(x=>x.classList.remove('active')); updateCursor(); paint(); });
  const shapesWrap=bar.querySelector('#vb-shapes-wrap');
  const shapesBtn=bar.querySelector('#vb-shapes-btn');
  shapesBtn.onclick=(e)=>{ e.stopPropagation(); const open=shapesWrap.classList.toggle('open'); shapesBtn.setAttribute('aria-expanded',open?'true':'false'); };
  bar.querySelectorAll('[data-shape]').forEach(b=>b.onclick=(e)=>{
    e.stopPropagation(); closeTextInput(true); vb.tool=b.dataset.shape; vb.sel=null;
    bar.querySelectorAll('[data-tool]').forEach(x=>x.classList.remove('active'));
    bar.querySelectorAll('[data-shape]').forEach(x=>x.classList.toggle('active',x===b));
    shapesBtn.classList.add('active'); updateCursor(); paint();
  });
  document.addEventListener('pointerdown', e=>{ if(shapesWrap && !shapesWrap.contains(e.target)){ shapesWrap.classList.remove('open'); shapesBtn.setAttribute('aria-expanded','false'); } });

  // ---------- tool-shaped mouse cursor ----------
  const cursorEl = document.createElement('div');
  cursorEl.className = 'vb-cursor';
  stage.appendChild(cursorEl);
  let cursorPos = null;   // pointer position in CSS px relative to the stage
  let cursorOver = false;
  const CUR_SIZE = 34;
  // hotspot (the point that must sit exactly on the pointer) inside the 24x24 icon grid
  const CUR_HOT = {pen:[3,29], hl:[3,29]};
  function cursorMarkup(){
    const scale = stage.getBoundingClientRect().width / VB_W;
    const k = CUR_SIZE/32;
    const glow = 'filter:drop-shadow(0 0 1px #fff) drop-shadow(0 0 1px #fff) drop-shadow(0 2px 3px rgba(0,0,0,.35));';
    if(vb.tool==='pen' || vb.tool==='hl'){
      const h = CUR_HOT[vb.tool];
      const ox = -h[0]*k, oy = -h[1]*k;
      return `<div style="position:absolute;left:${ox}px;top:${oy}px;${glow}">${vbIcon(vb.tool, CUR_SIZE, vb.color)}</div>
              <div style="position:absolute;left:-4px;top:-4px;width:8px;height:8px;border-radius:50%;background:${vb.color};border:1.5px solid #fff;box-shadow:0 0 0 1px rgba(0,0,0,.45);"></div>`;
    }
    if(vb.tool==='fill'){
      const k2 = CUR_SIZE/32;
      return `<div style="position:absolute;left:${-4*k2}px;top:${-29*k2}px;color:${vb.color};${glow}">${vbIcon('fill', CUR_SIZE, vb.color)}</div>`;
    }
    if(vb.tool==='erase'){
      // square eraser cursor; its side is directly proportional to the current thickness
      const d = Math.max(6, vb.size*4*scale);
      return `<div style="position:absolute;left:${-d/2}px;top:${-d/2}px;width:${d}px;height:${d}px;border:1.5px solid rgba(17,24,39,.85);background:rgba(255,255,255,.18);box-shadow:0 0 0 1px rgba(255,255,255,.75);box-sizing:border-box;"></div>`;
    }
    // Shapes intentionally use the normal mouse cursor; the selected shape must not follow the pointer.
    return null;
  }
  function placeCursor(){
    if(!cursorPos || !cursorOver || !cursorEl._on){ cursorEl.style.display='none'; return; }
    cursorEl.style.display='block';
    cursorEl.style.transform = `translate(${cursorPos[0]}px,${cursorPos[1]}px)`;
  }
  function updateCursor(){
    const m = cursorMarkup();
    if(m){ cursorEl.innerHTML = m; cursorEl._on = true; } else { cursorEl.innerHTML=''; cursorEl._on = false; }
    bar.querySelectorAll('[data-tool="pen"] svg, [data-tool="hl"] svg').forEach(el=>el.style.setProperty('--vb-ink', vb.color));
    canvas.style.cursor = vb.tool==='text' ? 'text' : (vb.tool==='select' ? 'default' : (['pen','hl','erase'].includes(vb.tool) ? 'none' : 'crosshair'));
    placeCursor();
  }
  const trackCursor = (e)=>{
    if(e.pointerType==='touch'){ cursorOver=false; placeCursor(); return; }
    const r = stage.getBoundingClientRect();
    cursorPos = [e.clientX-r.left, e.clientY-r.top];
    cursorOver = true; placeCursor();
  };
  canvas.addEventListener('pointerenter', trackCursor);
  canvas.addEventListener('pointermove', trackCursor);
  canvas.addEventListener('pointerleave', ()=>{ cursorOver=false; placeCursor(); });
  updateCursor();
  bar.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{
    vb.color=b.dataset.color; setActive('[data-color]','color',vb.color); bar.querySelector('#vb-custom').value=vb.color;
    if(vb.tool==='erase'){ vb.tool='pen'; setActive('[data-tool]','tool','pen'); }
    updateCursor();
  });
  bar.querySelector('#vb-custom').oninput=(e)=>{ vb.color=e.target.value; bar.querySelectorAll('[data-color]').forEach(b=>b.classList.remove('active')); updateCursor(); };
  const VB_SIZE_MIN = 1, VB_SIZE_MAX = 100, VB_PCT_MIN = 10, VB_PCT_MAX = 500;
  const sizeRange = bar.querySelector('#vb-size-range'), sizeInput = bar.querySelector('#vb-sizeval'), sizeLabel = bar.querySelector('#vb-sizelabel'), sizeUnit = bar.querySelector('#vb-sizeunit');
  const decBtn = bar.querySelector('#vb-size-dec'), incBtn = bar.querySelector('#vb-size-inc');
  let lastSel = null, selPct = 100, sizeKey = '';
  const scaling = ()=> vb.tool==='select' && !!vb.sel;   // +/- resize the selected object instead of changing the pen thickness
  const faNum = (n)=>Math.round(n).toLocaleString('fa-IR',{useGrouping:false});
  function updateRangeFill(){ const mn=parseFloat(sizeRange.min), mx=parseFloat(sizeRange.max), v=parseFloat(sizeRange.value); sizeRange.style.setProperty('--p', mx>mn ? Math.max(0,Math.min(1,(v-mn)/(mx-mn))) : 0); }
  function syncSizeUi(){
    if(vb.sel!==lastSel){ lastSel = vb.sel; selPct = 100; }
    const sc = scaling();
    const val = Math.round(sc ? selPct : vb.size);
    const key = (sc?'s':'t')+val;
    if(key===sizeKey) return;
    sizeKey = key;
    sizeLabel.textContent = sc ? 'اندازهٔ شیء' : 'ضخامت';
    sizeUnit.textContent = sc ? '٪' : '';
    sizeInput.title = sc ? 'درصد اندازهٔ شیء انتخاب‌شده؛ عدد دلخواه را بنویسید و Enter بزنید' : 'ضخامت (۱ تا ۱۰۰)؛ عدد دلخواه را بنویسید و Enter بزنید';
    if(document.activeElement!==sizeInput) sizeInput.value = faNum(val);
    sizeRange.min = sc ? VB_PCT_MIN : VB_SIZE_MIN; sizeRange.max = sc ? VB_PCT_MAX : VB_SIZE_MAX;
    sizeRange.value = Math.round(sc ? selPct : vb.size); updateRangeFill();
    decBtn.disabled = sc ? selPct<=VB_PCT_MIN : vb.size<=VB_SIZE_MIN;
    incBtn.disabled = sc ? selPct>=VB_PCT_MAX : vb.size>=VB_SIZE_MAX;
  }
  function setSize(n){
    vb.size = Math.max(VB_SIZE_MIN, Math.min(VB_SIZE_MAX, Math.round(n)));
    sizeKey = ''; syncSizeUi(); sizeRange.value=vb.size; updateRangeFill(); updateCursor();
  }
  // resize the selected object so it ends at `pct` percent of the size it had when it was selected
  function scaleSelectedTo(pct){
    const st = vb.sel; if(!st) return;
    pct = Math.max(VB_PCT_MIN, Math.min(VB_PCT_MAX, pct));
    if(Math.abs(pct-selPct) < 0.01) return;
    const f = pct/selPct;
    const p = pg();
    const last = p.hist[p.hist.length-1];
    if(last && last.k==='scale' && last.st===st && Date.now()-last.t < 1500){
      vbScale(st, f, last.cx, last.cy); last.f *= f; last.t = Date.now();   // merge quick repeated clicks into one undo step
    }else{
      const b = vbBounds(st), cx=(b.x1+b.x2)/2, cy=(b.y1+b.y2)/2;
      const from = p.strokes.indexOf(st); let to = from;
      if(p.strokes.slice(from+1).some(x=>x.t==='erase')){ p.strokes.splice(from,1); p.strokes.push(st); to = p.strokes.length-1; }
      vbScale(st, f, cx, cy);
      p.hist.push({k:'scale', st, f, cx, cy, from, to, t:Date.now()}); p.redo = [];
    }
    selPct = pct; sizeKey = '';
    rebuildBase(); paint(); refreshUi(); vbScheduleSave();
  }
  function stepSize(dir){
    if(scaling()) scaleSelectedTo(selPct + dir*10);
    else setSize(vb.size + dir);
  }
  function bindHold(btn, dir){
    let t1=null, t2=null;
    const stop=()=>{ clearTimeout(t1); clearInterval(t2); };
    btn.addEventListener('pointerdown',(e)=>{
      e.preventDefault(); stop();
      stepSize(dir);
      t1=setTimeout(()=>{ t2=setInterval(()=>stepSize(dir), 80); }, 400);
    });
    ['pointerup','pointerleave','pointercancel'].forEach(ev=>btn.addEventListener(ev,stop));
    btn.addEventListener('click',(e)=>{ if(e.detail===0) stepSize(dir); }); // keyboard
  }
  bindHold(decBtn, -1);
  bindHold(incBtn, +1);
  function commitTyped(){
    const n = parseFloat(toEnDigits(sizeInput.value).replace(/[^\d.]/g,''));
    if(isFinite(n)){ if(scaling()) scaleSelectedTo(n); else setSize(n); }
    sizeKey = ''; const hadFocus = document.activeElement===sizeInput;
    if(hadFocus) sizeInput.blur();
    syncSizeUi();
    sizeInput.value = faNum(scaling() ? selPct : vb.size);
  }
  sizeInput.addEventListener('focus', ()=>sizeInput.select());
  sizeInput.addEventListener('change', commitTyped);
  sizeInput.addEventListener('keydown', (e)=>{
    e.stopPropagation();
    if(e.key==='Enter'){ e.preventDefault(); commitTyped(); }
    else if(e.key==='ArrowUp'){ e.preventDefault(); stepSize(+1); sizeInput.value = faNum(scaling()?selPct:vb.size); }
    else if(e.key==='ArrowDown'){ e.preventDefault(); stepSize(-1); sizeInput.value = faNum(scaling()?selPct:vb.size); }
  });
  sizeInput.addEventListener('blur', ()=>{ sizeKey=''; syncSizeUi(); sizeInput.value = faNum(scaling() ? selPct : vb.size); });
  sizeRange.addEventListener('input', ()=>{
    const n=parseFloat(sizeRange.value);
    if(scaling()) scaleSelectedTo(n);
    else setSize(n);
    updateRangeFill();
  });
  sizeKey=''; syncSizeUi();

  function moveIdx(p, st, idx){
    const i = p.strokes.indexOf(st); if(i>=0) p.strokes.splice(i,1);
    p.strokes.splice(Math.min(idx, p.strokes.length), 0, st);
  }
  function applyBack(p, a){
    if(a.k==='resize'){ vbRestoreStroke(a.st,a.before); return; }
    if(a.k==='fill'){ a.st.fill=a.before; return; }
    if(a.k==='scale'){ vbScale(a.st, 1/a.f, a.cx, a.cy); moveIdx(p, a.st, a.from); return; }
    if(a.k==='add'){ const i=p.strokes.indexOf(a.st); if(i>=0) p.strokes.splice(i,1); }
    else if(a.k==='move'){
      vbTranslate(a.st, -a.dx, -a.dy);
      const i=p.strokes.indexOf(a.st); if(i>=0) p.strokes.splice(i,1);
      p.strokes.splice(Math.min(a.from, p.strokes.length), 0, a.st);
    }
    else if(a.k==='del'){ p.strokes.splice(Math.min(a.idx, p.strokes.length), 0, a.st); }
    else if(a.k==='clear'){ p.strokes = a.list.slice(); }
  }
  function applyForward(p, a){
    if(a.k==='resize'){ vbRestoreStroke(a.st,a.after); return; }
    if(a.k==='fill'){ a.st.fill=a.after; return; }
    if(a.k==='scale'){ vbScale(a.st, a.f, a.cx, a.cy); moveIdx(p, a.st, a.to); return; }
    if(a.k==='add'){ p.strokes.push(a.st); }
    else if(a.k==='move'){
      vbTranslate(a.st, a.dx, a.dy);
      const i=p.strokes.indexOf(a.st); if(i>=0) p.strokes.splice(i,1);
      p.strokes.splice(Math.min(a.to, p.strokes.length), 0, a.st);
    }
    else if(a.k==='del'){ const i=p.strokes.indexOf(a.st); if(i>=0) p.strokes.splice(i,1); }
    else if(a.k==='clear'){ p.strokes = []; }
  }
  const undo = ()=>{ const p=pg(); if(!p.hist.length || drag) return; const a=p.hist.pop(); applyBack(p,a); p.redo.push(a); selPct=100; sizeKey=''; rebuildBase(); paint(); refreshUi(); vbScheduleSave(); };
  const redo = ()=>{ const p=pg(); if(!p.redo.length || drag) return; const a=p.redo.pop(); applyForward(p,a); p.hist.push(a); selPct=100; sizeKey=''; rebuildBase(); paint(); refreshUi(); vbScheduleSave(); };
  bar.querySelector('#vb-undo').onclick=undo;
  bar.querySelector('#vb-redo').onclick=redo;
  bar.querySelector('#vb-clear').onclick=()=>{
    if(!pg().strokes.length) return;
    if(!confirm('همهٔ نوشته‌ها و نقاشی‌های این صفحه پاک شود؟')) return;
    const p = pg();
    p.hist.push({k:'clear', list:p.strokes.slice()}); p.redo = []; p.strokes = []; vb.sel = null;
    rebuildBase(); paint(); refreshUi(); vbScheduleSave();
  };
  function deleteSelected(){
    const p = pg();
    if(!vb.sel || vb.tool!=='select') return false;
    const idx = p.strokes.indexOf(vb.sel);
    if(idx<0) return false;
    p.hist.push({k:'del', st:vb.sel, idx}); p.redo = [];
    p.strokes.splice(idx,1); vb.sel = null;
    rebuildBase(); paint(); refreshUi(); vbScheduleSave();
    return true;
  }
  const goPage = (i)=>{ closeTextInput(true); vb.page=i; redrawAll(); };
  bar.querySelector('#vb-prev').onclick=()=>{ if(vb.page>0) goPage(vb.page-1); };
  bar.querySelector('#vb-next').onclick=()=>{ if(vb.page<vb.pages.length-1) goPage(vb.page+1); };
  bar.querySelector('#vb-addpage').onclick=()=>{ vb.pages.splice(vb.page+1,0,vbNewPage([])); goPage(vb.page+1); vbScheduleSave(); };
  bar.querySelector('#vb-delpage').onclick=()=>{
    if(vb.pages.length<=1) return;
    if(!confirm('این صفحه به‌طور کامل حذف شود؟')) return;
    vb.pages.splice(vb.page,1); vb.page=Math.min(vb.page, vb.pages.length-1); redrawAll(); vbScheduleSave();
  };
  bar.querySelector('#vb-bg').onchange=(e)=>{
    const prevDark = vbBgDef().dark;
    vb.bg = e.target.value;
    const nowDark = vbBgDef().dark;
    // keep default ink readable when switching between light and dark boards
    if(prevDark!==nowDark){
      if(nowDark && vb.color==='#111111') vb.color='#ffffff';
      else if(!nowDark && vb.color==='#ffffff') vb.color='#111111';
      setActive('[data-color]','color',vb.color); bar.querySelector('#vb-custom').value=vb.color;
      updateCursor();
    }
    paintBg(); vbScheduleSave();
  };
  bar.querySelector('#vb-png').onclick=()=>{
    const out = document.createElement('canvas'); out.width=canvas.width; out.height=canvas.height;
    const oc = out.getContext('2d'); oc.setTransform(K,0,0,K,0,0);
    vbDrawBackground(oc);
    oc.setTransform(1,0,0,1,0,0); oc.drawImage(base,0,0);
    out.toBlob(b=>{ if(b) downloadBlob(b, `تخته-مجازی-صفحه-${vb.page+1}.png`); }, 'image/png');
  };
  bar.querySelector('#vb-full').onclick=async()=>{
    try{
      if(document.fullscreenElement) await document.exitFullscreen();
      else if(root0.requestFullscreen) await root0.requestFullscreen();
      else alert('مرورگر شما حالت تمام‌صفحه را پشتیبانی نمی‌کند.');
    }catch(e){ alert('حالت تمام‌صفحه فعال نشد.'); }
  };
  function onKey(e){
    if(!document.body.contains(root0)){ document.removeEventListener('keydown', onKey); return; }
    if(e.target && /^(INPUT|TEXTAREA|SELECT)$/.test(e.target.tagName)) return;
    if((e.key==='Delete' || e.key==='Backspace') && vb.sel){ if(deleteSelected()) e.preventDefault(); return; }
    if((e.ctrlKey||e.metaKey) && !e.shiftKey && e.key.toLowerCase()==='z'){ e.preventDefault(); undo(); }
    else if((e.ctrlKey||e.metaKey) && (e.key.toLowerCase()==='y' || (e.shiftKey && e.key.toLowerCase()==='z'))){ e.preventDefault(); redo(); }
  }
  document.addEventListener('keydown', onKey);

  redrawAll();
}

function renderExamBuilderScreen(root){
  if(!root) return;
  if(!examBuilder) initExamBuilder();
  // هنگام تغییر نوع آزمون یا هر بازسازی، نسخه قبلی کاملاً جایگزین می‌شود.
  root.innerHTML='';
  const layout=document.createElement('div'); layout.className='exam-layout';
  const settings=document.createElement('div'); settings.className='exam-settings card';
  settings.innerHTML=`
    <div class="card-head"><div><h2 style="margin:0">آزمون‌ساز</h2><div class="muted" style="margin-top:4px">طراحی آزمون تستی و تشریحی با پیش‌نمایش زنده</div></div><span class="exam-type-badge">${examBuilder.type==='test'?'تستی':'تشریحی'}</span></div>
    <div class="field"><label>نوع آزمون</label><select id="ex-type"><option value="test" ${examBuilder.type==='test'?'selected':''}>آزمون تستی</option><option value="essay" ${examBuilder.type==='essay'?'selected':''}>آزمون تشریحی</option></select></div>
    <div class="field"><label>متن بالای آزمون</label><input id="ex-top" value="${examEsc(examBuilder.topText)}" placeholder="مثلاً بسمه تعالی"></div>
    <div class="field"><label>لوگوی آزمون</label><input id="ex-logo" type="file" accept="image/*"><div class="exam-logo-preview"><img src="${examBuilder.logo || DANIA_LOGO_DATA_URL}" alt="لوگوی دانیا">${examBuilder.logo?`<button class="btn danger small" id="ex-logo-remove">بازگشت به لوگوی دانیا</button>`:`<span style="font-size:11px;color:var(--ink-faint)">لوگوی پیش‌فرض دانیا</span>`}</div></div>
    <div class="grid">
      ${examInput('نام مدرسه','ex-school',examBuilder.school)}${examInput('عنوان آزمون','ex-title',examBuilder.title)}
      ${examInput('درس','ex-subject',examBuilder.subject)}${examInput('پایه / رشته','ex-grade',examBuilder.grade)}
      ${examInput('نام دبیر','ex-teacher',examBuilder.teacher)}${examInput('تاریخ','ex-date',examBuilder.date)}
      ${examInput('مدت آزمون','ex-duration',examBuilder.duration)}${examInput('شماره نوبت / توضیحات','ex-description',examBuilder.description)}
    </div>
    <hr style="border:0;border-top:1px solid var(--line);margin:16px 0">
    <div class="card-head" style="padding:0 0 10px"><h3 style="margin:0">سؤالات</h3><span class="muted">جمع بارم: ${examTotal()}</span></div>
    <div id="exam-q-editors"></div>
    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:10px"><button class="btn primary" id="ex-add">+ افزودن سؤال</button><button class="btn secondary" id="ex-save">ذخیره آزمون</button><button class="btn green" id="ex-print">چاپ / PDF</button></div>
  `;
  layout.appendChild(settings);
  const preview=document.createElement('div'); preview.className='exam-preview-wrap'; const paper=document.createElement('div'); paper.id='exam-preview-paper'; paper.className='exam-paper'; preview.appendChild(paper); layout.appendChild(preview); root.appendChild(layout);
  const qbox=settings.querySelector('#exam-q-editors');
  qbox.innerHTML=examBuilder.questions.map((q,i)=>{
    const opts=examBuilder.type==='test'?`<div class="field"><label>گزینه‌ها</label>${q.options.map((o,j)=>`<input value="${examEsc(o)}" placeholder="گزینه ${j+1}" data-q="${i}" data-opt="${j}" class="exam-option-input">`).join('')}</div>`:`<div class="grid">${examInput('تعداد خطوط پاسخ',`ex-lines-${i}`,q.answerLines||3,'type="number" min="1" max="12" data-q-lines="'+i+'"')}${examInput('راهنمای پاسخ',`ex-hint-${i}`,q.answerHint||'پاسخ خود را بنویسید.','data-q-hint="'+i+'"')}</div>`;
    return `<div class="exam-q-card"><div class="exam-q-head"><b>سؤال ${i+1}</b><div class="exam-tools"><button class="exam-icon" data-move="${i}" data-dir="-1">↑</button><button class="exam-icon" data-move="${i}" data-dir="1">↓</button><button class="exam-icon" data-remove="${i}">×</button></div></div><div class="grid">${examInput('شماره',`ex-num-${i}`,q.num,'data-q-num="'+i+'"')}${examInput('بارم',`ex-mark-${i}`,q.mark,'data-q-mark="'+i+'"')}</div><div class="field"><label>متن سؤال</label><input class="exam-question-input" type="text" data-q-text="${i}" value="${examEsc(q.text)}" placeholder="متن سؤال را وارد کنید..."></div><div class="field"><label>تصویر سؤال</label><input type="file" accept="image/*" data-q-image="${i}">${q.image?`<img src="${q.image}" style="max-width:100%;max-height:70px;display:block;margin-top:6px;border-radius:8px">`:''}</div>${opts}</div>`;
  }).join('');
  const update=(fn)=>{fn(); renderExamBuilderScreen(root);};
  settings.querySelector('#ex-type').onchange=e=>update(()=>{examBuilder.type=e.target.value;});
  ['top','school','title','subject','grade','teacher','date','duration','description'].forEach(k=>{settings.querySelector('#ex-'+k).oninput=e=>{examBuilder[{top:'topText',school:'school',title:'title',subject:'subject',grade:'grade',teacher:'teacher',date:'date',duration:'duration',description:'description'}[k]]=e.target.value; renderExamPreview(paper);};});
  settings.querySelector('#ex-logo').onchange=e=>{const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{examBuilder.logo=r.result;renderExamBuilderScreen(root)};r.readAsDataURL(f)};
  const removeLogo=settings.querySelector('#ex-logo-remove'); if(removeLogo) removeLogo.onclick=()=>{examBuilder.logo='';renderExamBuilderScreen(root)};
  settings.querySelector('#ex-add').onclick=()=>{const n=examBuilder.questions.length+1;examBuilder.questions.push({num:n,text:examBuilder.type==='test'?'متن سؤال جدید را وارد کنید.':'متن سؤال تشریحی جدید را وارد کنید.',mark:'۱',image:'',options:['گزینه اول','گزینه دوم','گزینه سوم','گزینه چهارم'],answerLines:4,answerHint:'پاسخ خود را بنویسید.'});renderExamBuilderScreen(root)};
  settings.querySelector('#ex-save').onclick=()=>{localStorage.setItem('dashboardExamBuilder',JSON.stringify(examBuilder));alert('آزمون در مرورگر ذخیره شد.');};
  settings.querySelector('#ex-print').onclick=()=>printDashboardExam();
  qbox.querySelectorAll('[data-q-num]').forEach(x=>x.oninput=()=>{examBuilder.questions[+x.dataset.qNum].num=x.value;renderExamPreview(paper)});
  qbox.querySelectorAll('[data-q-mark]').forEach(x=>x.oninput=()=>{examBuilder.questions[+x.dataset.qMark].mark=x.value;renderExamPreview(paper)});
  qbox.querySelectorAll('[data-q-text]').forEach(x=>x.oninput=()=>{examBuilder.questions[+x.dataset.qText].text=x.value;renderExamPreview(paper)});
  qbox.querySelectorAll('[data-opt]').forEach(x=>x.oninput=()=>{examBuilder.questions[+x.dataset.q].options[+x.dataset.opt]=x.value;renderExamPreview(paper)});
  qbox.querySelectorAll('[data-q-lines]').forEach(x=>x.oninput=()=>{examBuilder.questions[+x.dataset.qLines].answerLines=Math.max(1,Math.min(12,+x.value||1));renderExamPreview(paper)});
  qbox.querySelectorAll('[data-q-hint]').forEach(x=>x.oninput=()=>{examBuilder.questions[+x.dataset.qHint].answerHint=x.value;renderExamPreview(paper)});
  qbox.querySelectorAll('[data-q-image]').forEach(x=>x.onchange=()=>{const f=x.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{examBuilder.questions[+x.dataset.qImage].image=r.result;renderExamBuilderScreen(root)};r.readAsDataURL(f)});
  qbox.querySelectorAll('[data-remove]').forEach(x=>x.onclick=()=>{if(confirm('این سؤال حذف شود؟')){examBuilder.questions.splice(+x.dataset.remove,1);renderExamBuilderScreen(root)}});
  qbox.querySelectorAll('[data-move]').forEach(x=>x.onclick=()=>{const i=+x.dataset.move,j=i+(+x.dataset.dir);if(j>=0&&j<examBuilder.questions.length){[examBuilder.questions[i],examBuilder.questions[j]]=[examBuilder.questions[j],examBuilder.questions[i]];renderExamBuilderScreen(root)}});
  renderExamPreview(paper);
  requestAnimationFrame(rescaleExamPreview);
}
function rescaleExamPreview(){
  const wrap=document.querySelector('.exam-preview-wrap');
  const paper=document.getElementById('exam-preview-paper');
  if(!wrap||!paper)return;
  const base=794;
  const available=Math.max(280,wrap.clientWidth-8);
  const scale=Math.min(1,available/base);
  wrap.style.setProperty('--exam-scale',scale.toFixed(4));
  wrap.style.height=(1123*scale+24)+'px';
}
if(!window.__examResizeBound){
  window.__examResizeBound=true;
  window.addEventListener('resize',()=>{if(activeTab==='exam')requestAnimationFrame(rescaleExamPreview);});
}

function renderExamPreview(paper){
  if(!paper||!examBuilder)return;
  const logo=`<img class="exam-logo" src="${examBuilder.logo || DANIA_LOGO_DATA_URL}" alt="لوگوی دانیا">`;
  paper.innerHTML=`<div class="exam-top-text">${examEsc(examBuilder.topText)}</div><div class="exam-head"><div class="exam-head-top">${logo}<div><div class="exam-school">${examEsc(examBuilder.school)}</div><div class="exam-title">${examEsc(examBuilder.title)}</div></div><div class="exam-meta">درس: ${examEsc(examBuilder.subject)}<br>پایه/رشته: ${examEsc(examBuilder.grade)}<br>مدت: ${examEsc(examBuilder.duration)}</div></div><div class="exam-info"><span>دبیر: ${examEsc(examBuilder.teacher)}</span><span>تاریخ: ${examEsc(examBuilder.date)}</span><span>${examEsc(examBuilder.description)}</span></div><div class="exam-student"><span>نام و نام خانوادگی: ....................................</span><span>کلاس: ................</span><span>شماره: ................</span></div></div>${examBuilder.questions.length?examBuilder.questions.map(q=>`<div class="exam-q"><span class="exam-mark">بارم: ${examEsc(q.mark)}</span><div class="exam-qtext"><span class="exam-qnum">${examEsc(q.num)})</span>${examEsc(q.text).replace(/\n/g,'<br>')}</div>${q.image?`<img class="exam-qimg" src="${q.image}">`:''}${examBuilder.type==='test'?`<div class="exam-options" style="grid-template-columns:repeat(${examBuilder.layout||2},1fr)">${q.options.map((o,j)=>`<div class="exam-option"><span>${['الف','ب','ج','د'][j]}) ${examEsc(o)}</span></div>`).join('')}</div>`:`<div class="exam-answer-hint">${examEsc(q.answerHint||'پاسخ خود را بنویسید.')}</div><div class="exam-lines">${Array.from({length:q.answerLines||3},()=>'<div></div>').join('')}</div>`}</div>`).join(''):`<div class="empty">هنوز سؤالی اضافه نشده است.</div>`}<div class="exam-total">جمع بارم آزمون: ${examTotal()}</div>`;
}
